final class CountingJobDelivery implements BitrixWorkforceDeliveryClient{public int$calls=0;public function __construct(private?array$rows,private?BitrixWorkforceDeliveryReason$reason=null){}public function fetch():BitrixWorkforceDeliveryResult{$this->calls++;return$this->reason?new BitrixWorkforceDeliveryResult($this->reason,1,1,null):new BitrixWorkforceDeliveryResult(null,1,1,new BitrixWorkforceDeliveryBatch(count($this->rows??[]),$this->rows??[]));}}
function wjiWorker():array{return['ID'=>'501','ACTIVE'=>true,'LAST_NAME'=>'Иванов','NAME'=>'Иван','SECOND_NAME'=>'','WORK_POSITION'=>'Монтажник','EMAIL'=>'tab001042@example.test','UF_XING'=>'001042','UF_DEPARTMENT'=>[71],'UF_EMPLOYMENT_DATE'=>null];}
function wjiState(mysqli$db,string$p):array{$out=[];foreach(['fm2_workforce_sync_runs','fm2_workforce_observations','fm2_workforce_catalog','fm2_workforce_sync_metadata']as$table)$out[$table]=$db->query("SELECT * FROM `{$p}{$table}` ORDER BY 1")->fetch_all(MYSQLI_ASSOC);return$out;}
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_workforce_job_idem_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$other=new mysqli($host,$user,$password,$name,$port);$p='jobidem_';$identity='018f47ba-2f6d-4f80-8f42-0b37657fd911';
try{WorkforceCatalogSchemaMigration::apply($db,$p);BitrixWorkforceHistorySchemaMigration::apply($db,$p);$owner=new MariaDbWorkforceSynchronization($db,$p);$failed=new CountingJobDelivery(null,BitrixWorkforceDeliveryReason::TransportFailed);$one=$owner->runForJob($failed,$identity,1,'2026-09-09T10:00:00+03:00');assertSameValue(['failed','DELIVERY_TRANSPORT_FAILED',1],[$one['status'],$one['reason'],$failed->calls],'attempt1 failure recorded once');assertSameValue($one,$owner->runForJob($failed,$identity,1,'2026-09-09T10:01:00+03:00'),'same failed attempt replay exact');assertSameValue(1,$failed->calls,'failed replay does not fetch');
    $success=new CountingJobDelivery([wjiWorker()]);$two=$owner->runForJob($success,$identity,2,'2026-09-09T10:02:00+03:00');assertSameValue(['completed',1,1],[$two['status'],$two['delivered'],$success->calls],'fresh attempt2 publishes through native owner');$rows=$db->query("SELECT run_id,status FROM `{$p}fm2_workforce_sync_runs` ORDER BY started_at,run_id")->fetch_all(MYSQLI_ASSOC);assertSameValue([['run_id'=>$identity,'status'=>'failed'],['run_id'=>'0e3186a8-727a-4d2a-8d88-e57a7244e15c','status'=>'completed']],$rows,'literal attempt1/2 mapping and immutable statuses');assertSameValue(false,$rows[0]['run_id']===$rows[1]['run_id'],'attempt mapping is distinct');$observations=$db->query("SELECT * FROM `{$p}fm2_workforce_observations` ORDER BY id")->fetch_all(MYSQLI_ASSOC);assertSameValue($two,$owner->runForJob($success,$identity,2,'2026-09-09T10:03:00+03:00'),'lost success response replay exact');assertSameValue($two,$owner->runForJob($success,$identity,1,'2026-09-09T10:04:00+03:00'),'old attempt after newer success returns durable success');assertSameValue(1,$success->calls,'success replay and old attempt do not fetch');assertSameValue($observations,$db->query("SELECT * FROM `{$p}fm2_workforce_observations` ORDER BY id")->fetch_all(MYSQLI_ASSOC),'all replays duplicate no observations');
    $lock=$p.'bitrix_workforce_sync';$s=$other->prepare('SELECT GET_LOCK(?,0)');$s->bind_param('s',$lock);$s->execute();assertSameValue('1',(string)$s->get_result()->fetch_column(),'causal existing sync lock held');$blockedBefore=wjiState($db,$p);$blockedDelivery=new CountingJobDelivery([wjiWorker()]);$blocked=$owner->runForJob($blockedDelivery,'018f47ba-2f6d-4f80-8f42-0b37657fd912',1,'2026-09-09T10:05:00+03:00');assertSameValue(['failed','SYNC_ALREADY_RUNNING',0],[$blocked['status'],$blocked['reason'],$blockedDelivery->calls],'busy native lock returns retryable no-fetch result');assertSameValue($blockedBefore,wjiState($db,$p),'busy lock changes no run, observation, catalogue or metadata row');$release=$other->prepare('SELECT RELEASE_LOCK(?)');$release->bind_param('s',$lock);$release->execute();echo"PASS: WORKFORCE-JOB-IDEMPOTENCY-001 native retry/replay seam\n";
}finally{$other->close();$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
